(function() {
    'use strict';

    class EILeaderAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Inteligencia Emocional en el Liderazgo';
            this.version = '1.1.0';

            this.WEIGHTS = [
                {
                    morale:     { empathy: 1.2, selfCare: 0.3, support: 1.0, transparency: 0.7 },
                    reputation: { empathy: 0.5, selfCare: 0.0, support: 0.3, transparency: 1.2 },
                    patients:   { empathy: 0.3, selfCare: 0.0, support: 0.5, transparency: 0.3 },
                    wellbeing:  { empathy: 0.3, selfCare: 2.2, support: 0.0, transparency: 0.2 },
                    retention:  { empathy: 0.8, selfCare: 0.0, support: 1.2, transparency: 0.5 }
                },
                {
                    morale:     { empathy: 1.0, selfCare: 0.3, support: 1.5, transparency: 0.5 },
                    reputation: { empathy: 0.5, selfCare: 0.2, support: 0.5, transparency: 1.0 },
                    patients:   { empathy: 0.5, selfCare: 0.2, support: 0.8, transparency: 0.3 },
                    wellbeing:  { empathy: 0.3, selfCare: 2.5, support: 0.2, transparency: 0.2 },
                    retention:  { empathy: 0.8, selfCare: 0.2, support: 1.5, transparency: 0.3 }
                },
                {
                    morale:     { empathy: 1.3, selfCare: 0.2, support: 0.8, transparency: 1.0 },
                    reputation: { empathy: 1.5, selfCare: 0.0, support: 0.3, transparency: 1.5 },
                    patients:   { empathy: 1.0, selfCare: 0.2, support: 0.5, transparency: 0.5 },
                    wellbeing:  { empathy: 0.3, selfCare: 1.5, support: 0.2, transparency: 0.3 },
                    retention:  { empathy: 1.0, selfCare: 0.0, support: 0.8, transparency: 0.5 }
                },
                {
                    morale:     { empathy: 1.0, selfCare: 0.3, support: 1.0, transparency: 0.8 },
                    reputation: { empathy: 0.8, selfCare: 0.2, support: 0.5, transparency: 1.2 },
                    patients:   { empathy: 0.5, selfCare: 0.3, support: 0.8, transparency: 0.5 },
                    wellbeing:  { empathy: 0.5, selfCare: 2.0, support: 0.3, transparency: 0.3 },
                    retention:  { empathy: 0.8, selfCare: 0.2, support: 1.2, transparency: 0.5 }
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    morale: 25,
                    reputation: 40,
                    patients: 30,
                    wellbeing: 15,
                    retention: 35,
                    moraleHistory: [],
                    reputationHistory: [],
                    patientsHistory: [],
                    wellbeingHistory: [],
                    retentionHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    empathy: 5,
                    selfCare: 3,
                    support: 3,
                    transparency: 5
                };
            }
            this._setupSliderListeners();
            this._updateBriefing(state);
        }

        _setupSliderListeners() {
            var sliders = [
                { input: 'empathyInput', display: 'empathyValue' },
                { input: 'selfCareInput', display: 'selfCareValue' },
                { input: 'staffSupportInput', display: 'staffSupportValue' },
                { input: 'transparencyInput', display: 'transparencyValue' }
            ];
            sliders.forEach(function(s) {
                var el = document.getElementById(s.input);
                var disp = document.getElementById(s.display);
                if (el && disp) {
                    el.addEventListener('input', function() {
                        disp.textContent = el.value;
                    });
                }
            });
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, 3);
            var titleEl = document.getElementById('briefingTitle');
            var textEl = document.getElementById('briefingText');
            var badgeEl = document.getElementById('briefingBadge');
            var roundKeys = ['round1', 'round2', 'round3', 'round4'];
            var key = roundKeys[idx];

            if (titleEl) titleEl.innerHTML = window.mySimulation.t(key + '_title');
            if (textEl) textEl.innerHTML = window.mySimulation.t(key + '_desc');
            if (badgeEl) badgeEl.textContent = window.mySimulation.t('period_label') + ' ' + (idx + 1);

            this._updateKPIBars(state.domainState || {});
        }

        _updateKPIBars(ds) {
            var bars = [
                { id: 'moraleBar', val: ds.morale },
                { id: 'reputationBar', val: ds.reputation },
                { id: 'patientsBar', val: ds.patients },
                { id: 'wellbeingBar', val: ds.wellbeing },
                { id: 'retentionBar', val: ds.retention }
            ];
            bars.forEach(function(b) {
                var el = document.getElementById(b.id);
                if (el && b.val !== undefined) {
                    el.style.width = Math.max(0, Math.min(100, Math.round(b.val))) + '%';
                }
            });
        }

        _clamp(val) {
            return Math.max(0, Math.min(100, Math.round(val)));
        }

        _calcDelta(weights, decisions) {
            var base = -1;
            var delta = base;
            delta += weights.empathy * (decisions.empathy - 5);
            delta += weights.selfCare * (decisions.selfCare - 5);
            delta += weights.support * (decisions.support - 5);
            delta += weights.transparency * (decisions.transparency - 5);
            return delta;
        }

        validateDecisions(decisions) {
            var empIn = document.getElementById('empathyInput');
            var scIn = document.getElementById('selfCareInput');
            var ssIn = document.getElementById('staffSupportInput');
            var trIn = document.getElementById('transparencyInput');

            if (empIn) decisions.empathy = parseInt(empIn.value);
            if (scIn) decisions.selfCare = parseInt(scIn.value);
            if (ssIn) decisions.support = parseInt(ssIn.value);
            if (trIn) decisions.transparency = parseInt(trIn.value);

            if (decisions.empathy < 1 || decisions.empathy > 10 ||
                decisions.selfCare < 1 || decisions.selfCare > 10 ||
                decisions.support < 1 || decisions.support > 10 ||
                decisions.transparency < 1 || decisions.transparency > 10) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('input_warning'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var idx = Math.min((state.currentPeriod || 1) - 1, 3);
            var w = this.WEIGHTS[idx];

            var moraleDelta = this._calcDelta(w.morale, d);
            var reputationDelta = this._calcDelta(w.reputation, d);
            var patientsDelta = this._calcDelta(w.patients, d);
            var wellbeingDelta = this._calcDelta(w.wellbeing, d);
            var retentionDelta = this._calcDelta(w.retention, d);

            if (ds.wellbeing < 20) {
                moraleDelta = moraleDelta * 0.6;
                reputationDelta = reputationDelta * 0.6;
                patientsDelta = patientsDelta * 0.6;
                retentionDelta = retentionDelta * 0.6;
            }
            if (ds.morale < 15) {
                retentionDelta -= 4;
            }

            ds.morale = this._clamp(ds.morale + moraleDelta);
            ds.reputation = this._clamp(ds.reputation + reputationDelta);
            ds.patients = this._clamp(ds.patients + patientsDelta);
            ds.wellbeing = this._clamp(ds.wellbeing + wellbeingDelta);
            ds.retention = this._clamp(ds.retention + retentionDelta);

            ds.moraleHistory.push(ds.morale);
            ds.reputationHistory.push(ds.reputation);
            ds.patientsHistory.push(ds.patients);
            ds.wellbeingHistory.push(ds.wellbeing);
            ds.retentionHistory.push(ds.retention);

            var avgScore = Math.round((ds.morale + ds.reputation + ds.patients + ds.wellbeing + ds.retention) / 5);

            // Persist the round score into domainState so the grading/reporting
            // layer can read it. The server (results_utils.php::express_resolveDomainScore)
            // and the score timeline resolve, in order:
            //   domainState.performance.overallScore  ->  top-level domainState.score
            //   results.overallScore / results.score
            // Without this the instructor results panel shows an empty "-" score.
            ds.score = avgScore;
            ds.performance = { overallScore: avgScore, grade: this._grade(avgScore) };

            this._showFeedback(state, d, avgScore);

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1, domainState: ds });
            }, 500);

            return {
                period: state.currentPeriod,
                empathy: d.empathy,
                selfCare: d.selfCare,
                support: d.support,
                transparency: d.transparency,
                morale: ds.morale,
                reputation: ds.reputation,
                patients: ds.patients,
                wellbeing: ds.wellbeing,
                retention: ds.retention,
                avgScore: avgScore,
                score: avgScore,
                overallScore: avgScore
            };
        }

        _showFeedback(state, d, avgScore) {
            var panel = document.getElementById('feedbackPanel');
            var textEl = document.getElementById('feedbackText');
            if (!panel || !textEl) return;

            var idx = Math.min((state.currentPeriod || 1) - 1, 3);
            var msg = '';

            if (d.empathy >= 7 && d.transparency >= 7) {
                msg += window.mySimulation.t('fb_empathy_high');
            } else if (d.empathy <= 3) {
                msg += window.mySimulation.t('fb_empathy_low');
            }

            if (d.selfCare >= 7) {
                msg += '<br>' + window.mySimulation.t('fb_selfcare_high');
            } else if (d.selfCare <= 3) {
                msg += '<br>' + window.mySimulation.t('fb_selfcare_low');
            }

            if (d.support >= 7) {
                msg += '<br>' + window.mySimulation.t('fb_support_high');
            }

            if (state.domainState.wellbeing < 20) {
                msg += '<br>' + window.mySimulation.t('fb_burnout_warning');
            }

            if (avgScore >= 60) {
                msg += '<br>' + window.mySimulation.t('fb_overall_good');
            } else if (avgScore < 30) {
                msg += '<br>' + window.mySimulation.t('fb_overall_crisis');
            }

            if (msg.indexOf('<br>') === 0) { msg = msg.substring(4); }
            if (msg.length > 0) {
                textEl.innerHTML = msg;
                panel.style.display = 'block';
            } else {
                panel.style.display = 'none';
            }
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('moraleDisplay', 'domainState.morale', function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('reputationDisplay', 'domainState.reputation', function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('patientsDisplay', 'domainState.patients', function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('wellbeingDisplay', 'domainState.wellbeing', function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('retentionDisplay', 'domainState.retention', function(v) { return Math.round(v) + '/100'; });
        }

        getChartConfig() {
            return {
                metricsChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Staff Morale',
                                data: [],
                                borderColor: '#38b2ac',
                                backgroundColor: 'rgba(56,178,172,0.08)',
                                borderWidth: 2.5,
                                fill: false,
                                tension: 0.3,
                                pointRadius: 5,
                                pointBackgroundColor: '#38b2ac'
                            },
                            {
                                label: 'Public Reputation',
                                data: [],
                                borderColor: '#6b8cce',
                                backgroundColor: 'rgba(107,140,206,0.08)',
                                borderWidth: 2.5,
                                fill: false,
                                tension: 0.3,
                                pointRadius: 5,
                                pointBackgroundColor: '#6b8cce'
                            },
                            {
                                label: 'Patient Outcomes',
                                data: [],
                                borderColor: '#e8594e',
                                backgroundColor: 'rgba(232,89,78,0.08)',
                                borderWidth: 2.5,
                                fill: false,
                                tension: 0.3,
                                pointRadius: 5,
                                pointBackgroundColor: '#e8594e'
                            },
                            {
                                label: 'Leader Wellbeing',
                                data: [],
                                borderColor: '#e8a838',
                                backgroundColor: 'rgba(232,168,56,0.08)',
                                borderWidth: 2.5,
                                fill: false,
                                tension: 0.3,
                                pointRadius: 5,
                                pointBackgroundColor: '#e8a838'
                            },
                            {
                                label: 'Staff Retention',
                                data: [],
                                borderColor: '#a78bfa',
                                backgroundColor: 'rgba(167,139,250,0.08)',
                                borderWidth: 2.5,
                                fill: false,
                                tension: 0.3,
                                pointRadius: 5,
                                pointBackgroundColor: '#a78bfa'
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Hospital Metrics Over Time', color: '#8896b3' },
                            legend: { labels: { color: '#8896b3', boxWidth: 12, padding: 16 } }
