        getChartData(state) {
            var ds = state.domainState;
            var labels = ds.moraleHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                metricsChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.moraleHistory },
                        { data: ds.reputationHistory },
                        { data: ds.patientsHistory },
                        { data: ds.wellbeingHistory },
                        { data: ds.retentionHistory }
                    ]
                }
            };
        }

        _grade(avg) {
            if (avg >= 70) return 'Excellent';
            if (avg >= 55) return 'Good';
            if (avg >= 40) return 'Developing';
            return 'Needs Improvement';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};
            var avg = Math.round(((r.morale || 0) + (r.reputation || 0) + (r.patients || 0) + (r.wellbeing || 0) + (r.retention || 0)) / 5);

            var performance = this._grade(avg);

            var insights = [];
            if (r.wellbeing >= 60) insights.push(window.mySimulation.t('sum_wellbeing_good'));
            else insights.push(window.mySimulation.t('sum_wellbeing_low'));
            if (r.morale >= 60) insights.push(window.mySimulation.t('sum_morale_good'));
            else insights.push(window.mySimulation.t('sum_morale_low'));
            if (r.reputation >= 60) insights.push(window.mySimulation.t('sum_reputation_good'));

            return {
                finalScore: avg,
                overallScore: avg,
                totalPeriods: history.length,
                performance: performance,
                morale: r.morale,
                reputation: r.reputation,
                patients: r.patients,
                wellbeing: r.wellbeing,
                retention: r.retention,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var t = function(k) { return window.mySimulation.t(k); };
            var score = (typeof summary.overallScore === 'number') ? summary.overallScore
                      : (typeof summary.finalScore === 'number' ? summary.finalScore : 0);
            var perf = summary.performance || this._grade(score);
            var tierKey = { 'Excellent': 'tier_excellent', 'Good': 'tier_good',
                            'Developing': 'tier_developing', 'Needs Improvement': 'tier_needs' }[perf];
            var perfL = tierKey ? t(tierKey) : perf;
            var color = score >= 70 ? '#38b2ac' : (score >= 40 ? '#e8a838' : '#e8594e');

            var kpis = [
                [t('morale_label'),     summary.morale],
                [t('reputation_label'), summary.reputation],
                [t('patients_label'),   summary.patients],
                [t('wellbeing_label'),  summary.wellbeing],
                [t('retention_label'),  summary.retention]
            ];
            var kpiRow = kpis.map(function(k) {
                var v = (typeof k[1] === 'number') ? Math.round(k[1]) : '—';
                return '<span style="display:inline-block;margin:4px 10px;"><strong>' + v + '</strong> ' + k[0] + '</span>';
            }).join('');

            var ins = summary.insights || [];
            var items = ins.map(function(x) { return '<li>' + x + '</li>'; }).join('');
            var insBlock = items ? ('<ul style="text-align:left;margin:12px auto 0;display:inline-block;">' + items + '</ul>') : '';

            return '<div class="completion-message text-center p-4">' +
                '<h4 style="margin-bottom:8px;">' + t('completion_heading') + '</h4>' +
                '<div style="font-size:2.6rem;font-weight:800;color:' + color + ';">' + score + '/100</div>' +
                '<p class="lead" style="margin:2px 0;">' + t('overall_score_label') + '</p>' +
                '<p style="font-weight:600;color:' + color + ';">' + perfL + '</p>' +
                '<p class="text-muted" style="margin:8px 0;">' + kpiRow + '</p>' +
                insBlock +
                '<hr class="my-3"><p class="text-muted">' + t('thanks_msg') + '</p></div>';
        }

